word customer.discounted-balance(customer: Customer) -> Money {
    effects none
    let balance = customer::balance(customer)
    let amount = Money::value(balance)
    let quotient = ::divide(amount, 10)
    let multiple-of-ten = ::multiply(quotient, 10)
    let remainder = ::subtract(amount, multiple-of-ten)
    let whole-part = ::multiply(quotient, 9)
    let fractional-part = ::divide(::multiply(remainder, 9), 10)
    let discounted = ::add(whole-part, fractional-part)
    if ::equals(customer::kind(customer), "premium") {
        Money::new(discounted)
    } else {
        balance
    }
}

responses.data:
word customer.discounted-balance(customer: Customer) -> Money {
    effects none
    let balance = customer::balance(customer)
    let amount = Money::value(balance)
    let quotient = ::divide(amount, 10)
    let multiple-of-ten = ::multiply(quotient, 10)
    let remainder = ::subtract(amount, multiple-of-ten)
    let whole-part = ::multiply(quotient, 9)
    let fractional-part = ::divide(::multiply(remainder, 9), 10)
    let discounted = ::add(whole-part, fractional-part)
    if ::equals(customer::kind(customer), "premium") {
        Money::new(discounted)
    } else {
        balance
    }
}
